const SPA_ROUTES={"index.html":"home","shop.html":"shop","price-list.html":"price-list","product.html":"product","categories.html":"categories","technology.html":"technology","gallery.html":"gallery","store-locator.html":"store-locator","about.html":"about","contact.html":"contact","login.html":"login","signup.html":"signup","cart.html":"cart","checkout.html":"checkout","order-confirmation.html":"order-confirmation","support.html":"support","sitemap.html":"sitemap","privacy.html":"privacy","terms.html":"terms","shipping-returns.html":"shipping-returns","discount.html":"discount","wishlist.html":"wishlist"};
function getPageParams(){if(location.hash.startsWith("#/")){const q=location.hash.indexOf("?");return new URLSearchParams(q>=0?location.hash.slice(q+1):"")}return new URLSearchParams(location.search)}
function navigateTo(href){try{const u=new URL(href,location.href);const file=(u.pathname.split("/").pop()||"index.html").toLowerCase();const route=SPA_ROUTES[file]||"home";const query=u.search||"";const next="#/"+route+query;if(location.hash===next){window.dispatchEvent(new HashChangeEvent("hashchange"))}else location.hash=next}catch(e){location.href=href}}
const money = n => "Rs. " + Number(n||0).toLocaleString("en-PK");
const escapeHtml = s => String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
function getCart(){try{return JSON.parse(localStorage.getItem("albertoCart")||"[]")}catch(e){return []}}
function setCart(cart){localStorage.setItem("albertoCart",JSON.stringify(cart));updateCartCount()}
function cartCount(){return getCart().reduce((s,x)=>s+x.qty,0)}
function updateCartCount(){$(".cart-count").text(cartCount())}
function toast(msg){const el=$(`<div class="site-toast" role="status"></div>`).text(msg);$("#toast-area").append(el);el.hide().fadeIn(180);setTimeout(()=>el.fadeOut(250,()=>el.remove()),2800)}
function addToCart(id,qty=1){const p=PRODUCTS.find(x=>x.id===Number(id));if(!p)return;let c=getCart(),item=c.find(x=>x.id===p.id);if(item)item.qty+=Number(qty);else c.push({id:p.id,qty:Number(qty)});setCart(c);toast(`${p.name} added to your cart.`)}
function changeQty(id,delta){let c=getCart(),x=c.find(y=>y.id===Number(id));if(x)x.qty+=delta;c=c.filter(x=>x.qty>0);setCart(c);renderCartPage()}
function removeItem(id){setCart(getCart().filter(x=>x.id!==Number(id)));renderCartPage()}
function clearCart(){setCart([]);renderCartPage()}
function getCheckoutItems(){const params=getPageParams();const buyId=Number(params.get("buy")||0);if(buyId){const p=PRODUCTS.find(x=>x.id===buyId),qty=Math.max(1,Math.min(20,Number(params.get("qty")||1)));return p?[{id:p.id,qty}]:[]}return getCart()}
function getCouponSettings(){const c=typeof ALBERTO_CONFIG!=="undefined"?ALBERTO_CONFIG:{};const coupon=c.coupon||{};const offers=c.offers||{};return {priceThreshold:Number(offers.priceThreshold??5000),pricePercent:Number(offers.pricePercent??15),quantityThreshold:Number(offers.quantityThreshold??3),quantityPercent:Number(offers.quantityPercent??7),couponCode:String(coupon.code??"037123"),couponPercent:Number(coupon.percent??20),code:String(coupon.code??"037123"),percent:Number(coupon.percent??20),active:coupon.active!==false}}
function activeCoupon(){const code=String(localStorage.getItem("albertoCoupon")||"").trim();const c=getCouponSettings();return c.active&&code===c.couponCode?{code:c.couponCode,percent:c.couponPercent,source:"Coupon code"}:null}
function cartTotals(items=getCart()){const subtotal=items.reduce((s,x)=>{const p=PRODUCTS.find(p=>p.id===x.id);return s+(p?p.price*Number(x.qty||0):0)},0);const quantity=items.reduce((n,x)=>n+Number(x.qty||0),0);const settings=getCouponSettings();const candidates=[];if(settings.active&&subtotal>=settings.priceThreshold)candidates.push({code:"",percent:settings.pricePercent,source:"Order value offer"});if(settings.active&&quantity>=settings.quantityThreshold)candidates.push({code:"",percent:settings.quantityPercent,source:"Quantity offer"});const coupon=activeCoupon();if(coupon)candidates.push(coupon);candidates.sort((a,b)=>b.percent-a.percent);const best=candidates[0]||null;const discount=best?Math.round(subtotal*best.percent/100):0;const shipping=0;return {subtotal,discount,shipping,total:Math.max(0,subtotal-discount+shipping),coupon:discount?best:null,quantity}}
/* ===== Wishlist: saved per signed-in user (or as a guest) in this browser's localStorage ===== */
const WISHLIST_PREFIX="albertoWishlist:";
const HEART_SVG='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z"></path></svg>';
function wishlistOwner(){try{const u=JSON.parse(localStorage.getItem("albertoSignedIn")||"null");const e=u&&u.email?String(u.email).trim().toLowerCase():"";return e?"user:"+e:"guest"}catch(e){return "guest"}}
function wishlistKey(owner){return WISHLIST_PREFIX+(owner||wishlistOwner())}
function wishlistCatalogue(){return PRODUCTS.length?PRODUCTS:(Array.isArray(window.ALBERTO_PRODUCTS)?window.ALBERTO_PRODUCTS:[])}
function readWishlistKey(key){let raw=null;try{raw=localStorage.getItem(key);if(!raw)return[];const arr=JSON.parse(raw);if(!Array.isArray(arr))throw new Error("Stored wishlist is not a list");const seen=new Set(),out=[];arr.forEach(x=>{const id=Number(x&&typeof x==="object"?x.id:x);if(Number.isInteger(id)&&id>0&&!seen.has(id)){seen.add(id);out.push({id,addedAt:Number(x&&x.addedAt)||0})}});return out}catch(e){console.error("Could not read saved wishlist",e);try{if(raw)localStorage.setItem(key+"_corrupt_"+Date.now(),raw)}catch(e2){}return[]}}
function writeWishlistKey(key,list){try{const json=JSON.stringify(list);localStorage.setItem(key,json);return localStorage.getItem(key)===json}catch(e){console.error("Could not save wishlist",e);return false}}
function getWishlist(){const list=readWishlistKey(wishlistKey()),cat=wishlistCatalogue();return cat.length?list.filter(w=>cat.some(p=>p.id===w.id)):list}
function wishlistIds(){return new Set(getWishlist().map(w=>w.id))}
function wishlistCount(){return getWishlist().length}
function setWishlist(id,want){id=Number(id);const p=wishlistCatalogue().find(x=>x.id===id);if(!p)return null;const key=wishlistKey(),list=readWishlistKey(key),i=list.findIndex(x=>x.id===id);if(want&&i<0)list.push({id,addedAt:Date.now()});else if(!want&&i>=0)list.splice(i,1);if(!writeWishlistKey(key,list)){toast("Your wishlist could not be saved. Please allow site storage in your browser.");return null}return want}
function toggleWishlist(id){return setWishlist(id,!wishlistIds().has(Number(id)))}
function mergeGuestWishlist(){const owner=wishlistOwner();if(owner==="guest")return;const gk=wishlistKey("guest"),uk=wishlistKey(owner),g=readWishlistKey(gk);if(!g.length)return;const u=readWishlistKey(uk);g.forEach(x=>{if(!u.some(y=>y.id===x.id))u.push(x)});if(writeWishlistKey(uk,u)){try{localStorage.removeItem(gk)}catch(e){}}}
function wishlistButton(p,variant,extra){extra=extra?" "+extra:"";const on=wishlistIds().has(p.id),name=escapeHtml(p.name),title=on?"Remove from wishlist":"Add to wishlist";if(variant==="text")return `<button type="button" class="wishlist-btn wishlist-btn-text${on?" is-active":""}${extra}" data-id="${p.id}" data-name="${name}" aria-pressed="${on}" title="${title}">${HEART_SVG}<span class="wishlist-label">${on?"In Wishlist":"Add to Wishlist"}</span></button>`;return `<button type="button" class="wishlist-btn wishlist-btn-card${on?" is-active":""}" data-id="${p.id}" data-name="${name}" aria-pressed="${on}" aria-label="Wishlist: ${name}" title="${title}">${HEART_SVG}</button>`}
function updateWishlistUI(){const ids=wishlistIds();$(".wishlist-count").text(ids.size);$(".wishlist-btn[data-id]").each(function(){const $b=$(this),on=ids.has(Number($b.attr("data-id")));$b.toggleClass("is-active",on).attr("aria-pressed",on?"true":"false").attr("title",on?"Remove from wishlist":"Add to wishlist");$b.find(".wishlist-label").text(on?"In Wishlist":"Add to Wishlist")})}
function renderWishlist(){return `${pageHero("Your Wishlist","Watches and clocks you have saved for later.")}<section class="content-section"><div class="container"><div id="wishlist-meta" class="small-muted mb-3"></div><div id="wishlist-items"></div></div></section>`}
function wishlistCard(p){const name=escapeHtml(p.name);return `<div class="col"><article class="product-card wishlist-card" role="link" tabindex="0" data-product-href="pages/product.html?id=${p.id}" aria-label="View ${name} details"><div class="product-img-wrap">${p.discount?`<span class="badge-gold">${p.discount}% OFF</span>`:""}<a class="product-card-link" href="pages/product.html?id=${p.id}" tabindex="-1"><img class="product-img" src="${p.image}" alt="${name}" loading="lazy" onerror="this.onerror=null;this.src='images/logo.jpeg'"></a></div><div class="product-info"><div class="small-muted mb-1">${escapeHtml(p.category)}</div><h3><a class="product-card-link" href="pages/product.html?id=${p.id}">${name}</a></h3><div class="price mb-3">${money(p.price)} ${p.originalPrice?`<span class="old-price">${money(p.originalPrice)}</span>`:""}</div><div class="d-grid gap-2"><button class="btn btn-gold btn-sm add-cart" type="button" data-id="${p.id}">Add to Cart</button><button class="btn btn-outline-forest btn-sm wishlist-remove" type="button" data-id="${p.id}">Remove</button></div></div></article></div>`}
function renderWishlistPage(){const $box=$("#wishlist-items");if(!$box.length)return;const cat=wishlistCatalogue(),items=getWishlist().sort((a,b)=>b.addedAt-a.addedAt).map(w=>cat.find(p=>p.id===w.id)).filter(Boolean);$("#wishlist-meta").html(wishlistOwner()==="guest"?`Saved in this browser. <a href="pages/login.html">Sign in</a> to keep it with your account.`:"Saved to your account on this browser.");if(!items.length){$box.html('<div class="empty-state"><h3>Your wishlist is empty</h3><p class="text-secondary">Tap the heart on any watch to save it here for later.</p><a class="btn btn-gold" href="pages/shop.html">Explore watches</a></div>');return}$box.html(`<div class="row row-cols-1 row-cols-sm-2 row-cols-lg-4 g-4">${items.map(wishlistCard).join("")}</div>`)}
function refreshWishlist(){updateWishlistUI();renderWishlistPage()}
$(document).on("click",".wishlist-btn",function(e){e.preventDefault();e.stopPropagation();const id=Number($(this).attr("data-id")),p=wishlistCatalogue().find(x=>x.id===id);if(!p)return;const added=toggleWishlist(id);if(added===null)return;refreshWishlist();toast(added?`${p.name} added to your wishlist.`:`${p.name} removed from your wishlist.`)});
$(document).on("click",".wishlist-remove",function(e){e.preventDefault();e.stopPropagation();const id=Number($(this).attr("data-id")),p=wishlistCatalogue().find(x=>x.id===id);if(!p)return;if(setWishlist(id,false)===null)return;refreshWishlist();$("#wishlist-items").attr("tabindex","-1").css("outline","none").trigger("focus");toast(`${p.name} removed from your wishlist.`)});
window.addEventListener("storage",e=>{if(e.key===null||e.key==="albertoSignedIn"||(e.key&&e.key.indexOf(WISHLIST_PREFIX)===0))refreshWishlist()});
window.addEventListener("pageshow",e=>{if(e.persisted)refreshWishlist()});
function header(){return `<div class="announcement"><div class="announcement-track"><div class="announcement-group">${Array(6).fill('<span>TIMELESS STYLE, EVERY DAY &nbsp; • &nbsp; DISCOVER YOUR SIGNATURE WATCH</span>').join("")}</div><div class="announcement-group">${Array(6).fill('<span>TIMELESS STYLE, EVERY DAY &nbsp; • &nbsp; DISCOVER YOUR SIGNATURE WATCH</span>').join("")}</div></div></div><nav class="navbar navbar-expand-lg site-nav"><div class="container"><a class="navbar-brand" href="index.html" aria-label="Alberto Watches home"><img src="images/logo.jpeg" alt="Alberto Watches"></a><a class="nav-home-wordmark d-none d-xl-flex" href="index.html"><span>ALBERTO</span><small>WATCH COMPANY</small></a><div class="header-actions order-lg-3"><a class="header-icon-link account-shortcut" href="pages/login.html" aria-label="Login or sign up" title="Account"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="12" cy="8" r="3.5"></circle><path d="M5 20c.7-3.4 3.2-5.2 7-5.2s6.3 1.8 7 5.2"></path></svg></a><a class="header-icon-link wishlist-drawer-link" href="pages/wishlist.html" aria-label="Wishlist" title="Wishlist">${HEART_SVG}<span class="count-pill wishlist-count">${wishlistCount()}</span></a><a class="header-icon-link cart-drawer-link" href="pages/cart.html" aria-label="Shopping cart" title="Cart"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M3 4h2l2.2 10.2a2 2 0 0 0 2 1.6h7.9a2 2 0 0 0 1.9-1.4L21 8H6"></path><circle cx="10" cy="20" r="1"></circle><circle cx="18" cy="20" r="1"></circle></svg><span class="count-pill cart-count">0</span></a><span class="header-visitor d-inline">Visitors <b id="site-visitor-count">—</b></span></div><button class="navbar-toggler order-lg-2" type="button" data-bs-toggle="collapse" data-bs-target="#mainNav" aria-controls="mainNav" aria-expanded="false" aria-label="Toggle navigation"><span class="navbar-toggler-icon"></span></button><div class="collapse navbar-collapse order-lg-1" id="mainNav"><ul class="navbar-nav mx-auto align-items-lg-center"><li class="nav-item"><a class="nav-link" href="index.html">Home</a></li><li class="nav-item"><a class="nav-link" href="pages/shop.html">Products</a></li><li class="nav-item"><a class="nav-link" href="pages/technology.html">Technology</a></li><li class="nav-item"><a class="nav-link" href="pages/store-locator.html">Store Locator</a></li><li class="nav-item"><a class="nav-link" href="pages/support.html">Support</a></li><li class="nav-item dropdown"><a class="nav-link dropdown-toggle" href="#" id="navMoreMenu" role="button" data-bs-toggle="dropdown" aria-expanded="false">Explore</a><ul class="dropdown-menu dropdown-menu-end" aria-labelledby="navMoreMenu"><li><a class="dropdown-item" href="pages/price-list.html">Price List</a></li><li><a class="dropdown-item" href="pages/gallery.html">Gallery</a></li><li><a class="dropdown-item" href="pages/categories.html">Categories</a></li><li><a class="dropdown-item" href="pages/discount.html">Special Offers</a></li><li><a class="dropdown-item" href="pages/about.html">About Us</a></li><li><a class="dropdown-item" href="pages/contact.html">Contact</a></li></ul></li></ul><div class="mobile-account-links d-lg-none"><a href="pages/login.html">Login / Sign Up</a><a href="pages/cart.html">View Cart (<span class="cart-count">0</span>)</a><a href="pages/wishlist.html">Wishlist (<span class="wishlist-count">${wishlistCount()}</span>)</a></div></div></div></nav>`}
function tickerItem(first){const idAttr=n=>first?` id="ticker-${n}"`:"";return `<span class="live-info-item"${first?"":' aria-hidden="true"'}><span class="ticker-date"${idAttr("date")}>Date: Loading…</span><span aria-hidden="true">•</span><span class="ticker-time"${idAttr("time")}>Time: Loading…</span><span aria-hidden="true">•</span><span class="ticker-location"${idAttr("location")}>Location: Waiting for browser permission…</span><span aria-hidden="true">•</span><span>Alberto Watch Company</span><span class="live-info-sep" aria-hidden="true">•</span></span>`}
