function productCard(p){return `<div class="col"><article class="product-card" role="link" tabindex="0" data-product-href="pages/product.html?id=${p.id}" aria-label="View ${escapeHtml(p.name)} details"><div class="product-img-wrap">${p.discount?`<span class="badge-gold">${p.discount}% OFF</span>`:""}${wishlistButton(p,"card")}<a class="product-card-link" href="pages/product.html?id=${p.id}" tabindex="-1"><img class="product-img" src="${p.image}" alt="${escapeHtml(p.name)}" loading="lazy" onerror="this.onerror=null;this.src='images/logo.jpeg'"></a></div><div class="product-info"><div class="small-muted mb-1">${escapeHtml(p.category)}</div><h3><a class="product-card-link" href="pages/product.html?id=${p.id}">${escapeHtml(p.name)}</a></h3><div class="rating mb-2">★★★★★ <span class="small-muted">(${p.rating} · ${p.reviews})</span></div><div class="price mb-3">${money(p.price)} ${p.originalPrice?`<span class="old-price">${money(p.originalPrice)}</span>`:""}</div><button class="btn btn-gold btn-sm w-100 view-watch" type="button" data-id="${p.id}">Quick View <span aria-hidden="true">→</span></button></div></article></div>`}
function renderHome(){return `<section class="video-hero video-carousel-wrap"><div id="watchVideoCarousel" class="carousel slide carousel-fade" data-bs-ride="false" data-bs-interval="false" data-bs-pause="false" data-bs-touch="true"><div class="carousel-indicators"><button type="button" data-bs-target="#watchVideoCarousel" data-bs-slide-to="0" class="active" aria-current="true" aria-label="Watch video 1"></button><button type="button" data-bs-target="#watchVideoCarousel" data-bs-slide-to="1" aria-label="Watch video 2"></button><button type="button" data-bs-target="#watchVideoCarousel" data-bs-slide-to="2" aria-label="Watch video 3"></button></div><div class="carousel-inner"><div class="carousel-item active"><video class="video-hero-media" autoplay muted playsinline preload="auto" poster="images/banners/banner-1.jpeg" aria-label="Alberto watches hero video"><source src="images/videos/user-video-1-web.mp4" type="video/mp4"></video></div><div class="carousel-item"><video class="video-hero-media" muted playsinline preload="metadata" poster="images/banners/banner-4.jpeg" aria-label="Alberto watches video two"><source src="images/videos/user-video-2-web.mp4" type="video/mp4"></video></div><div class="carousel-item"><video class="video-hero-media" muted playsinline preload="metadata" poster="images/banners/banner-5.jpeg" aria-label="Alberto watches video three"><source src="images/videos/watch-carousel-3.mp4" type="video/mp4"></video></div></div><button class="carousel-control-prev" type="button" data-bs-target="#watchVideoCarousel" data-bs-slide="prev" aria-label="Previous video"><span class="carousel-control-prev-icon" aria-hidden="true"></span></button><button class="carousel-control-next" type="button" data-bs-target="#watchVideoCarousel" data-bs-slide="next" aria-label="Next video"><span class="carousel-control-next-icon" aria-hidden="true"></span></button><div class="video-hero-overlay"></div><div class="container video-hero-content"><div class="hero-kicker mb-3">The signature collection</div><h1>Time, shaped into <em>something timeless.</em></h1><p class="my-4">Meet watch designs inspired by enduring craftsmanship, confident simplicity and the moments that matter.</p><a class="btn btn-gold" href="pages/shop.html">Shop the collection →</a></div></div></section><section class="section-pad"><div class="container"><div class="section-head d-flex flex-column flex-md-row justify-content-between align-items-md-end"><div><div class="eyebrow">Shop by mood</div><h2>Find your kind of time.</h2><p class="mb-0">A considered style for every chapter of your day.</p></div><a class="btn btn-outline-forest mt-3 mt-md-0" href="pages/categories.html">All categories</a></div><div class="row g-3"><div class="col-md-6 col-lg-3"><a class="category-tile d-block" href="pages/shop.html?category=Luxury"><span class="eyebrow">01 / Refined</span><h3 class="mt-3">Luxury</h3><span>Explore →</span></a></div><div class="col-md-6 col-lg-3"><a class="category-tile d-block" href="pages/shop.html?category=Classic"><span class="eyebrow">02 / Essential</span><h3 class="mt-3">Classic</h3><span>Explore →</span></a></div><div class="col-md-6 col-lg-3"><a class="category-tile d-block" href="pages/shop.html?category=Chronograph"><span class="eyebrow">03 / Dynamic</span><h3 class="mt-3">Chronograph</h3><span>Explore →</span></a></div><div class="col-md-6 col-lg-3"><a class="category-tile d-block" href="pages/shop.html?category=Smartwatch"><span class="eyebrow">04 / Connected</span><h3 class="mt-3">Smartwatch</h3><span>Explore →</span></a></div></div></div></section><section class="section-pad soft-bg"><div class="container"><div class="section-head text-center"><div class="eyebrow">The edit</div><h2>Featured watches</h2><p class="mx-auto">Distinct looks, carefully curated for the modern watch enthusiast.</p></div><div class="row row-cols-1 row-cols-sm-2 row-cols-lg-4 g-4" id="featured-products"></div><div class="text-center mt-4"><a class="btn btn-outline-forest" href="pages/shop.html">Discover the full collection</a></div></div></section><section class="section-pad"><div class="container"><div class="row align-items-center g-5"><div class="col-lg-5"><div class="eyebrow">Why Alberto</div><h2 class="display-5">The beauty is in the details.</h2><p class="text-secondary">A watch can be more than a way to tell time. It can be a daily ritual, a thoughtful gift and a small expression of who you are.</p><a href="pages/about.html" class="btn btn-gold">Our philosophy</a></div><div class="col-lg-7"><div class="row g-3"><div class="col-md-6"><div class="feature-box"><div class="feature-icon">✦</div><h4>Considered design</h4><p class="small-muted mb-0">Balanced forms and versatile styling designed to feel at home beyond trends.</p></div></div><div class="col-md-6"><div class="feature-box"><div class="feature-icon">◷</div><h4>Time well spent</h4><p class="small-muted mb-0">A collection concept built around everyday wearability and personal moments.</p></div></div><div class="col-md-6"><div class="feature-box"><div class="feature-icon">◇</div><h4>Room to explore</h4><p class="small-muted mb-0">Compare classic, sport, vintage and connected watch styles in one place.</p></div></div><div class="col-md-6"><div class="feature-box"><div class="feature-icon">♡</div><h4>Helpful guidance</h4><p class="small-muted mb-0">Browse educational notes and support information before choosing a style.</p></div></div></div></div></div></div></section><section class="section-pad voucher-section"><div class="container"><div class="section-head d-flex flex-column flex-md-row justify-content-between align-items-md-end"><div><div class="eyebrow">A little something extra</div><h2>Private offers, timeless style.</h2><p class="mb-0">Use a valid voucher at checkout to see your discount instantly.</p></div><a href="pages/checkout.html" class="btn btn-outline-forest mt-3 mt-md-0">Apply a voucher →</a></div><div class="row g-4"><div class="col-md-6"><article class="voucher-card voucher-dark"><div><span class="voucher-label">WELCOME PRIVILEGE</span><span class="voucher-percent" id="home-coupon-percent">5% OFF</span><h3>Enjoy a little more.</h3><p>Enter the active welcome code at checkout and your saving will appear in the order summary.</p></div><div class="voucher-code-row"><span class="voucher-code" id="home-coupon-code">LEEHAN01</span><button type="button" class="btn btn-light btn-sm copy-coupon" data-code="LEEHAN01">Copy code</button></div></article></div><div class="col-md-6"><article class="voucher-card voucher-gold"><div><span class="voucher-label">THE ALBERTO EDIT</span><h3>Good taste, thoughtfully priced.</h3><p>Enter the current voucher at checkout to see eligible savings applied to your order.</p></div><a href="pages/shop.html" class="btn btn-dark mt-3">Explore the collection →</a></article></div></div></div></section><section class="promo-band"><div class="container d-md-flex align-items-center justify-content-between gap-4"><div><div class="eyebrow">Your next everyday classic</div><h2 class="mt-2">A good watch feels like you.</h2><p class="mb-0 text-white-50">Explore the collection and find your signature style.</p></div><a class="btn btn-gold mt-4 mt-md-0" href="pages/shop.html">Shop watches →</a></div></section><section class="section-pad soft-bg"><div class="container"><div class="section-head text-center"><div class="eyebrow">Kind words</div><h2>Notes from our community</h2><p class="mx-auto">Share feedback about browsing and product information. Submitted reviews are saved in this browser.</p></div><div id="customer-reviews" class="row g-4"></div><div class="feature-box mt-4"><h3>Write a review</h3><form id="review-form"><div class="row g-3"><div class="col-md-4"><label class="form-label" for="review-name">Your name</label><input id="review-name" name="name" class="form-control" required minlength="2"></div><div class="col-md-3"><label class="form-label" for="review-rating">Rating</label><select id="review-rating" name="rating" class="form-select" required><option value="5">5 stars</option><option value="4">4 stars</option><option value="3">3 stars</option><option value="2">2 stars</option><option value="1">1 star</option></select></div><div class="col-md-5"><label class="form-label" for="review-title">Review title</label><input id="review-title" name="title" class="form-control" required minlength="3"></div><div class="col-12"><label class="form-label" for="review-text">Your review</label><textarea id="review-text" name="text" class="form-control" rows="3" required minlength="10" maxlength="600"></textarea></div><div class="col-12"><button type="submit" class="btn btn-gold">Submit review</button><div id="review-feedback" class="mt-3" aria-live="polite"></div></div></div></form></div></div></section>`}
function renderShop(){return `${pageHero("The Watch Collection","Explore watches and a dedicated collection of 20 wall and desk clocks. Use category filters to browse watches or clocks separately.")}<section class="content-section"><div class="container"><div class="filter-panel mb-4"><div class="row g-3 align-items-end"><div class="col-lg-4"><label class="form-label" for="product-search">Search products</label><input id="product-search" class="form-control" placeholder="Name or description"></div><div class="col-sm-6 col-lg-2"><label class="form-label" for="category-filter">Category</label><select id="category-filter" class="form-select"><option value="">All categories</option></select></div><div class="col-sm-6 col-lg-2"><label class="form-label" for="sort-filter">Sort by</label><select id="sort-filter" class="form-select"><option value="featured">Featured</option><option value="price-asc">Price: low to high</option><option value="price-desc">Price: high to low</option><option value="name-asc">Name: A–Z</option><option value="name-desc">Name: Z–A</option><option value="rating-desc">Top rated</option></select></div><div class="col-sm-6 col-lg-2"><label class="form-label" for="max-price">Maximum price</label><select id="max-price" class="form-select"><option value="1000000">Any price</option><option value="3500">Up to Rs. 3,500</option><option value="3750">Up to Rs. 3,750</option><option value="4000">Up to Rs. 4,000</option></select></div><div class="col-sm-6 col-lg-2"><button type="button" class="btn btn-outline-forest w-100" id="clear-filters">Clear filters</button></div></div></div><div class="d-flex justify-content-between align-items-center mb-3"><span id="result-count" class="small-muted">Loading collection…</span><span class="small-muted">Prices shown in PKR</span></div><div id="product-grid" class="row row-cols-1 row-cols-sm-2 row-cols-lg-4 g-4"></div><div id="no-results" class="empty-state d-none mt-3"><h3>No products found</h3><p class="text-secondary">Try another search or clear your filters.</p><button type="button" class="btn btn-gold" id="empty-clear">Clear filters</button></div></div></section>`}
function renderProduct(){return `${pageHero("Product Details","Explore features and details for your selected watch.")}<section class="content-section"><div class="container" id="product-detail"></div></section><section class="section-pad soft-bg"><div class="container"><div class="section-head"><div class="eyebrow">You may also like</div><h2>Related styles</h2></div><div class="row row-cols-1 row-cols-sm-2 row-cols-lg-4 g-4" id="related-products"></div></div></section>`}
function renderCategories(){return `${pageHero("Collections & Categories","Choose a watch style that suits your day.")}<section class="section-pad"><div class="container"><div class="row g-4">${[["Luxury","Elevated finishes and refined styling."],["Classic","Clean silhouettes made for everyday wear."],["Vintage","Characterful designs inspired by another era."],["Smartwatch","Connected and digital watch concepts."],["Chronograph","Sport-inspired dials and technical styling."],["Men's","Versatile styles across dress and casual looks."],["Women's","Elegant and expressive everyday designs."],["Automatic","A look at mechanical watchmaking traditions."],["Clocks","Explore 20 dedicated wall and desk clock designs in the Alberto Clocks collection."]].map(([n,d])=>`<div class="col-md-6 col-lg-3"><a class="category-tile d-block h-100" href="pages/shop.html?category=${encodeURIComponent(n)}"><div class="eyebrow">Explore collection</div><h3 class="mt-3">${n}</h3><p class="text-white-50">${d}</p><span>View watches →</span></a></div>`).join("")}</div></div></section>`}

function renderPriceList(){return `${pageHero("Watch Price List","Compare every watch in the collection, including category and listed discount.")}<section class="content-section"><div class="container"><div class="pl-wrap"><table class="pl-table"><thead><tr><th>Product</th><th>Category</th><th>Price</th><th>Discount</th><th class="text-end">Details</th></tr></thead><tbody id="price-list-body"></tbody></table></div><p class="small-muted pl-note">All prices are listed in Pakistani Rupees (PKR). Delivery is confirmed separately.</p><a class="btn btn-gold" href="pages/shop.html">Shop watches</a></div></section>`}
function renderPriceListRows(){const body=$("#price-list-body");if(!body.length)return;body.html(PRODUCTS.map(p=>`<tr><td data-label="Product"><div class="pl-product"><img src="${p.image}" alt="${escapeHtml(p.name)}" class="pl-thumb"><strong>${escapeHtml(p.name)}</strong></div></td><td data-label="Category"><span class="pl-cat">${escapeHtml(p.category)}</span></td><td data-label="Price"><span class="pl-price">${money(p.price)}</span></td><td data-label="Discount">${p.discount?`<span class="pl-off">${p.discount}% OFF</span>`:'<span class="pl-none">—</span>'}</td><td data-label="Details" class="text-end"><button class="btn btn-outline-forest btn-sm view-watch" type="button" data-id="${p.id}">Quick view</button></td></tr>`).join(""))}
function renderTechnology(){return `${pageHero("The Art &amp; Technology of Time","A beginner-friendly guide to common watch movements, functions and materials.")}<section class="content-section"><div class="container"><div class="row g-4">${[["Quartz movement","A battery-powered quartz crystal regulates timekeeping. Quartz watches are commonly low-maintenance and practical."],["Automatic movement","An automatic mechanical movement uses a rotor powered by wrist motion to wind its mainspring."],["Mechanical watches","Mechanical watches store energy in a mainspring and use gears and an escapement to regulate it."],["Chronographs","A chronograph adds a stopwatch function to a watch. Controls and sub-dials vary by model."],["Smartwatch features","Smartwatches may offer notifications, activity tracking and apps. Features depend on the specific device."],["Water resistance","Water-resistance ratings are model-specific. Never assume a concept image or listing is suitable for swimming."],["Materials &amp; straps","Cases and straps may use steel, titanium, ceramic, leather, silicone or other materials; confirm actual product specs."],["Watch maintenance","Keep watches clean and follow the manufacturer's guidance for servicing, battery changes and storage."],["Clocks & timepieces","Clocks use similar timekeeping principles in wall, desk and decorative formats. Browse the Clocks category in the shop to see the Alberto Clocks collection of 20 wall and desk clocks."]].map(([h,p])=>`<div class="col-md-6"><div class="feature-box"><div class="eyebrow">Watch guide</div><h3>${h}</h3><p class="text-secondary mb-0">${p}</p></div></div>`).join("")}</div><div class="alert alert-warning mt-4">Accuracy note: this page is general education. Product-specific movement, materials and water resistance are not independently verified for this catalogue.</div></div><div class="feature-box mt-4"><h3>Clocks and other timepieces</h3><p class="text-secondary mb-0">Clocks use the same core timekeeping principles as watches, but are designed for desks, walls and shared spaces. Common styles include analogue wall clocks, digital desk clocks and alarm clocks. Our dedicated Alberto Clocks collection of 20 wall and desk clocks is available in the shop: <a href="pages/shop.html?category=Clocks">browse the Clocks category</a>.</p></div></section>`}
function renderGallery(){return `${pageHero("The Alberto Gallery","Explore the visual language of our illustrative watch collection.")}<section class="content-section"><div class="container"><div class="row row-cols-2 row-cols-md-3 row-cols-lg-4 g-3" id="gallery-grid"></div><div class="modal fade" id="galleryModal" tabindex="-1" aria-hidden="true"><div class="modal-dialog modal-dialog-centered modal-lg"><div class="modal-content bg-dark text-white"><div class="modal-header border-0"><h5 class="modal-title">Collection gallery</h5><button type="button" class="btn-close btn-close-white" data-bs-dismiss="modal" aria-label="Close"></button></div><div class="modal-body text-center"><button type="button" class="btn btn-outline-light me-3" id="gallery-prev">← Previous</button><img id="gallery-large" class="img-fluid" src="images/logo.jpeg" alt="Selected watch"><button type="button" class="btn btn-outline-light ms-3" id="gallery-next">Next →</button><p id="gallery-caption" class="mt-3 mb-0"></p></div></div></div></div></div></section>`}
function renderLocator(){return `${pageHero("Store Locator","Explore contact and location information for Alberto Watches.")}<section class="content-section"><div class="container"><div class="row g-4"><div class="col-lg-6"><div class="feature-box"><h3>Find nearby options</h3><p class="text-secondary">Choose the button to request your browser location. Your location is not requested automatically.</p><button type="button" id="locate-me" class="btn btn-gold">Use my current location</button><div id="location-result" class="mt-3 small-muted">Location permission has not been requested.</div></div><div class="feature-box mt-4"><h3>Local time</h3><div id="live-clock" class="display-6 serif">Loading…</div><div id="live-date" class="text-secondary"></div><p class="small-muted mt-2">Date and time use your device's local clock.</p></div><div class="feature-box mt-4"><h3>Visit counter</h3><div class="display-6 serif" id="visit-count">—</div><p class="small-muted mb-0">Stored only in this browser's localStorage; not a global visitor count.</p></div></div><div class="col-lg-6"><div class="feature-box"><div class="eyebrow">Find us</div><h3>Karachi service area</h3><p class="text-secondary">Office 12, Main University Road, Gulshan-e-Iqbal, Karachi, Sindh, Pakistan.</p><div class="ratio ratio-4x3 rounded overflow-hidden"><iframe title="Map of Gulshan-e-Iqbal, Karachi" src="https://www.openstreetmap.org/export/embed.html?bbox=67.055%2C24.91%2C67.105%2C24.95&amp;layer=mapnik&amp;marker=24.93%2C67.08" loading="lazy" referrerpolicy="no-referrer-when-downgrade"></iframe></div><a class="btn btn-outline-forest mt-3" target="_blank" rel="noopener" href="https://www.openstreetmap.org/?mlat=24.93&amp;mlon=67.08#map=14/24.93/67.08">Open larger map</a><p class="small-muted mt-3 mb-0">Map shows the general area; call ahead to confirm availability before visiting.</p></div></div></div></div></section>`}
function renderAbout(){return `${pageHero("A point of view on time","Thoughtfully styled timepieces for everyday moments and special occasions.")}<section class="section-pad"><div class="container"><div class="row align-items-center g-5"><div class="col-lg-6"><img src="images/8.jpeg" class="img-fluid" alt="Green dial watch concept"></div><div class="col-lg-6"><div class="eyebrow">Our introduction</div><h2 class="display-5">Good design should feel effortless.</h2><p class="text-secondary">Alberto Watches brings together a considered range of timepiece styles, from understated classics to contemporary sport designs. Our collection is organised to make it easy to discover, compare and choose a look that suits your day.</p><p class="text-secondary">We value clear product information, comfortable styling and a straightforward shopping experience. Product specifications should always be confirmed before purchase.</p></div></div><div class="row g-4 mt-4"><div class="col-md-4"><div class="feature-box"><h3>Mission</h3><p class="text-secondary mb-0">Make watch discovery clear, elegant and accessible.</p></div></div><div class="col-md-4"><div class="feature-box"><h3>Vision</h3><p class="text-secondary mb-0">Show how thoughtful design and simple technology can create a helpful shopping experience.</p></div></div><div class="col-md-4"><div class="feature-box"><h3>Values</h3><p class="text-secondary mb-0">Clarity, usability, timeless design and honest product information.</p></div></div></div><div class="row g-4 mt-1"><div class="col-12"><div class="feature-box"><div class="eyebrow">Get in touch</div><h3>Contact details</h3><p class="text-secondary mb-0">Email: <a href="mailto:info@albertowatches.com">info@albertowatches.com</a><br>Phone: <a href="tel:+923001234567">+92 300 1234567</a><br>Address: Office 12, Main University Road, Gulshan-e-Iqbal, Karachi, Sindh, Pakistan<br>Hours: Monday–Saturday, 10:00–18:00 PKT</p></div></div></div></div></section>`}
function renderContact(){return `${pageHero("Let's talk","Questions about a style or an order? Send us a message and we will be glad to help.")}<section class="content-section"><div class="container"><div class="row g-5"><div class="col-lg-7"><form id="contact-form" class="feature-box"><h2 class="mb-4">Send a message</h2><div class="row g-3"><div class="col-md-6"><label class="form-label" for="contact-name">Full name</label><input id="contact-name" name="name" class="form-control" autocomplete="name" required minlength="2"></div><div class="col-md-6"><label class="form-label" for="contact-email">Email address</label><input id="contact-email" name="email" type="email" class="form-control" autocomplete="email" required></div><div class="col-12"><label class="form-label" for="contact-subject">Subject</label><input id="contact-subject" name="subject" class="form-control" required></div><div class="col-12"><label class="form-label" for="contact-message">Message</label><textarea id="contact-message" name="message" class="form-control" rows="5" required minlength="10"></textarea></div><div class="col-12"><button class="btn btn-gold" type="submit">Send message</button><div id="contact-feedback" class="mt-3" aria-live="polite"></div></div></div></form></div><div class="col-lg-5"><div class="feature-box"><div class="eyebrow">Contact details</div><h3>We're here to help</h3><p class="text-secondary">Email: <a href="mailto:info@albertowatches.com">info@albertowatches.com</a><br>Phone: <a href="tel:+923001234567">+92 300 1234567</a><br>Address: Office 12, Main University Road, Gulshan-e-Iqbal, Karachi, Sindh, Pakistan.</p><h5>Business hours</h5><p class="text-secondary">Monday–Saturday<br>10:00 AM – 6:00 PM (PKT)</p><p class="small-muted">For store visits, please contact us first to confirm availability and opening hours.</p><a class="btn btn-outline-forest" href="pages/support.html">Visit support &amp; FAQ</a></div></div></div></div></section>`}
function renderLogin(){return `${pageHero("Welcome back","Sign in to continue your Alberto Watches experience.")}<section class="auth-section"><div class="container"><div class="auth-split"><aside class="auth-visual"><img src="images/9.jpeg" alt="Alberto automatic watch"><div class="auth-visual-copy"><span class="eyebrow">ALBERTO WATCH COMPANY</span><h2>Time is personal.</h2><p>Discover considered designs, save your favourites and keep your collection close.</p></div></aside><div class="auth-panel"><div class="icon-circle mb-3">◷</div><h2>Sign in</h2><p class="small-muted">Use the email and password you registered with on this browser.</p><form id="login-form"><div class="mb-3"><label class="form-label" for="login-email">Email address</label><input id="login-email" name="email" type="email" class="form-control" autocomplete="email" required></div><div class="mb-3"><label class="form-label" for="login-password">Password</label><div class="input-group"><input id="login-password" name="password" type="password" class="form-control" autocomplete="current-password" required minlength="8"><button type="button" class="btn btn-outline-secondary toggle-password" data-target="login-password">Show</button></div></div><button class="btn btn-gold w-100 mt-2" type="submit">Sign in</button><div id="login-feedback" class="mt-3" aria-live="polite"></div></form><p class="mt-4 mb-0 text-center">New to Alberto? <a href="pages/signup.html"><strong>Create an account</strong></a></p><p class="small-muted text-center mt-3 mb-0">Local project account only; do not reuse an important password.</p></div></div></div></section>`}
function renderSignup(){return `${pageHero("Create your account","Join the Alberto Watches experience.")}<section class="auth-section"><div class="container"><div class="auth-split"><aside class="auth-visual"><img src="images/3.jpeg" alt="Classic watch on display"><div class="auth-visual-copy"><span class="eyebrow">YOUR NEXT CHAPTER</span><h2>A classic of your own.</h2><p>Create an account to sign in on this browser and continue exploring the collection.</p></div></aside><div class="auth-panel"><div class="icon-circle mb-3">✦</div><h2>Create account</h2><p class="small-muted">Fill in your details to register on this device.</p><form id="signup-form"><div class="mb-3"><label class="form-label" for="signup-name">Full name</label><input id="signup-name" name="name" class="form-control" autocomplete="name" required minlength="2"></div><div class="mb-3"><label class="form-label" for="signup-email">Email address</label><input id="signup-email" name="email" type="email" class="form-control" autocomplete="email" required></div><div class="mb-3"><label class="form-label" for="signup-phone">Pakistani mobile number</label><input id="signup-phone" name="phone" type="tel" class="form-control" inputmode="tel" placeholder="03XXXXXXXXX" pattern="(?:\\+92|0092|0)?[\\s\\-]*3(?:[\\s\\-]*[0-9]){9}" required></div><div class="mb-3"><label class="form-label" for="signup-password">Password</label><div class="input-group"><input id="signup-password" name="password" type="password" class="form-control" autocomplete="new-password" required minlength="8"><button type="button" class="btn btn-outline-secondary toggle-password" data-target="signup-password">Show</button></div></div><div class="mb-3"><label class="form-label" for="signup-confirm">Confirm password</label><input id="signup-confirm" name="confirmPassword" type="password" class="form-control" autocomplete="new-password" required minlength="8"></div><div class="form-check mb-3"><input class="form-check-input" type="checkbox" name="terms" id="terms-check" required><label class="form-check-label" for="terms-check">I agree to the <a href="pages/terms.html">terms and conditions</a>.</label></div><button class="btn btn-gold w-100" type="submit">Create account</button><div id="signup-feedback" class="mt-3" aria-live="polite"></div></form><p class="mt-4 mb-0 text-center">Already registered? <a href="pages/login.html"><strong>Sign in</strong></a></p><p class="small-muted text-center mt-3 mb-0">Your account is saved in this browser on this device.</p></div></div></div></section>`}
