function renderLegal(kind){let title=kind==="privacy"?"Privacy Policy":kind==="terms"?"Terms &amp; Conditions":"Shipping &amp; Returns";let body=kind==="privacy"?["This is a student-project store. The cart, visitor counter and order confirmation use browser localStorage on the device where the site is opened.","No server-side account, payment, contact-message or newsletter processing is connected. Do not enter sensitive personal information.","A production website needs a reviewed privacy notice, consent and retention practices appropriate to its jurisdiction."]:kind==="terms"?["This website is supplied as an academic store, not a live retail service.","Catalog prices, product images, product features, reviews and sample locations are illustrative and must be verified before publication.","No purchase contract, payment processing, warranty or delivery promise is created by using this demo."]:["Shipping and delivery rates shown in the demo are sample calculations only.","Returns and exchanges require a verified retailer policy and may depend on local consumer law.","Before a real launch, publish clear eligibility, time limits, condition requirements, refund timing and contact channels."];return `${pageHero(title,"Important information about this store website.")}<section class="content-section"><div class="container legal-copy">${body.map(p=>`<p class="text-secondary">${p}</p>`).join("")}<p><a href="pages/contact.html" class="btn btn-outline-forest">Contact page</a></p></div></section>`}


let PRODUCTS=[];
async function loadProducts(){try{if(Array.isArray(window.ALBERTO_PRODUCTS)&&window.ALBERTO_PRODUCTS.length){PRODUCTS=window.ALBERTO_PRODUCTS;return}const r=await fetch("documentation/products.json");if(!r.ok)throw new Error("Could not load products.json");PRODUCTS=await r.json()}catch(e){console.error(e);$("#page-content").prepend('<div class="container alert alert-danger mt-3">Product data could not load. Please check that js/products-data.js is present.</div>')}}
function renderCartPage(){if(!$("body").is('[data-page="cart"]'))return;let cart=getCart(),$items=$("#cart-items"),$sum=$("#cart-summary");if(!cart.length){$items.html('<div class="empty-state"><h3>Your bag is waiting</h3><p class="text-secondary">You have not added any watches yet.</p><a class="btn btn-gold" href="pages/shop.html">Explore watches</a></div>');$sum.html('<h3>Order summary</h3><p class="text-secondary">Add a watch to see your totals.</p>');return}let html=cart.map(x=>{let p=PRODUCTS.find(p=>p.id===x.id);if(!p)return "";return `<div class="cart-line d-flex gap-3 align-items-center"><img src="${p.image}" alt="${escapeHtml(p.name)}"><div class="flex-grow-1"><a href="pages/product.html?id=${p.id}"><strong>${escapeHtml(p.name)}</strong></a><div class="small-muted">${money(p.price)} each</div><div class="qty-control mt-2"><button type="button" class="btn btn-link text-danger p-0 remove-item" data-id="${p.id}">Remove</button><span class="qty-stepper"><button type="button" class="qty-minus" data-id="${p.id}" aria-label="Decrease quantity">−</button><span class="qty-value">${x.qty}</span><button type="button" class="qty-plus" data-id="${p.id}" aria-label="Increase quantity">+</button></span></div></div><strong>${money(p.price*x.qty)}</strong></div>`}).join("");$items.html(html+'<button type="button" class="clear-bag-btn" id="clear-cart">Clear bag</button>');let t=cartTotals(cart);$sum.html(`<h3>Order summary</h3><div class="d-flex justify-content-between mt-4"><span>Subtotal</span><strong>${money(t.subtotal)}</strong></div>${t.discount?`<div class="d-flex justify-content-between mt-2 text-success"><span>${escapeHtml(t.coupon.source==="Coupon code"?`Coupon ${t.coupon.code}`:t.coupon.source)} (${t.coupon.percent}%)</span><strong>− ${money(t.discount)}</strong></div>`:""}<div class="d-flex justify-content-between mt-2"><span>Delivery</span><strong>Confirmed separately</strong></div><hr><div class="d-flex justify-content-between fs-5"><strong>Total before delivery</strong><strong>${money(t.total)}</strong></div><a href="pages/checkout.html" class="btn btn-gold w-100 mt-3">Continue to checkout</a><a href="pages/shop.html" class="btn btn-outline-forest w-100 mt-2">Continue shopping</a>`)}
function renderCheckoutSummary(){const items=getCheckoutItems();const t=cartTotals(items);const first=items.length?PRODUCTS.find(p=>p.id===items[0].id):null;const totalQty=items.reduce((n,x)=>n+x.qty,0);if(first){$("#checkout-product-image").attr("src",first.image).attr("alt",first.name);$("#checkout-product-name").text(items.length===1?first.name:`${items.length} selected watches`);$("#checkout-product-description").text(items.length===1?first.description:`${totalQty} items selected for your order.`);$("#checkout-product-lines").html(items.map(x=>{const p=PRODUCTS.find(y=>y.id===x.id);return p?`<div class="checkout-product-line"><span>${escapeHtml(p.name)} <small>× ${x.qty}</small></span><strong>${money(p.price*x.qty)}</strong></div>`:""}).join(""))}else{$("#checkout-product-name").text("Your bag is empty");$("#checkout-product-description").text("Choose a watch before continuing.");$("#checkout-product-lines").empty()}const discountLabel=t.coupon?(t.coupon.source==="Coupon code"?`Coupon (${t.coupon.code})`:t.coupon.source):"Discount";$("#checkout-summary").html(items.length?`<div class="d-flex justify-content-between py-2"><span>Subtotal</span><strong>${money(t.subtotal)}</strong></div>${t.discount?`<div class="d-flex justify-content-between py-2 text-success"><span>${escapeHtml(discountLabel)} (${t.coupon.percent}%)</span><strong>− ${money(t.discount)}</strong></div>`:""}<div class="d-flex justify-content-between py-2"><span>Delivery</span><strong class="small">Confirmed separately</strong></div><hr><div class="d-flex justify-content-between fs-5"><strong>Total before delivery</strong><strong>${money(t.total)}</strong></div>`:'<p>Your cart is empty. <a href="pages/shop.html">Shop watches</a> or choose a product to buy now.</p>');const saved=activeCoupon();if(saved){$("#coupon-input").val(saved.code);$("#coupon-feedback").removeClass("text-danger").addClass("text-success").text(`Coupon ${saved.code} entered. Best eligible discount is shown in the order summary.`)}}

function renderDetail(){const id=Number(getPageParams().get("id")||1),p=PRODUCTS.find(x=>x.id===id)||PRODUCTS[0];if(!p)return;$("#product-detail").html(`<div class="row g-5 align-items-start"><div class="col-lg-6"><img class="detail-img" src="${p.image}" alt="${escapeHtml(p.name)}"></div><div class="col-lg-6"><div class="eyebrow">${escapeHtml(p.category)} collection</div><h2 class="display-5 mt-2">${escapeHtml(p.name)}</h2><div class="rating mb-3">★★★★★ <span class="small-muted">${p.rating} / 5 · ${p.reviews} customer ratings</span></div><div class="price fs-3 mb-3">${money(p.price)} ${p.originalPrice?`<span class="old-price">${money(p.originalPrice)}</span> `:""}${p.discount?`<span class="badge text-bg-success">${p.discount}% OFF</span>`:""}</div><p class="text-secondary">${escapeHtml(p.description)}</p><ul class="mb-4">${p.features.map(x=>`<li>${escapeHtml(x)}</li>`).join("")}<li>Movement: ${escapeHtml(p.movement)}</li>${/^not applicable$/i.test(String(p.strap||"").trim())?"":`<li>Strap: ${escapeHtml(p.strap)}</li>`}<li>Water resistance: ${escapeHtml(p.waterResistance)}</li></ul><div class="alert alert-warning">Please confirm product specifications and availability with us before ordering.</div><div class="d-flex gap-3 align-items-center mt-4"><div><label class="form-label d-block" for="detail-qty">Quantity</label><div class="qty-stepper detail-qty-stepper"><button type="button" class="detail-qty-minus" aria-label="Decrease quantity">−</button><span class="qty-value" id="detail-qty" data-qty="1">1</span><button type="button" class="detail-qty-plus" aria-label="Increase quantity">+</button></div></div><div class="pt-4"><button type="button" class="btn btn-gold detail-add" data-id="${p.id}">Add to Cart</button></div></div><button type="button" class="btn btn-whatsapp mt-3 w-100 buy-whatsapp" data-id="${p.id}">Buy on WhatsApp</button>${wishlistButton(p,"text","mt-3 w-100")}</div></div>`);$("#related-products").html(PRODUCTS.filter(x=>x.category===p.category&&x.id!==p.id).slice(0,4).map(productCard).join("")||PRODUCTS.filter(x=>x.id!==p.id).slice(0,4).map(productCard).join(""))}
/* Customer reviews storage: one key, read-modify-write, never truncated, never silently overwritten */
/* Featured sample reviews: built into the code so every browser shows the same six reviews. Reviews submitted by visitors are saved in their own browser and shown first. */
const FEATURED_REVIEWS=[
{name:"Ayesha Khan",title:"Elegant and comfortable",rating:5,date:"2026-08-12",text:"I ordered a classic watch for my brother's birthday and the black and gold finish looks far more expensive than the price. The strap is comfortable and the delivery was quick."},
{name:"Hamza Ali",title:"Great value for money",rating:5,date:"2026-08-26",text:"The chronograph I picked has a clean dial and feels solid on the wrist. Ordering through WhatsApp was easy and the team answered all my questions politely."},
{name:"Sana Malik",title:"Beautiful wall clock",rating:4,date:"2026-09-03",text:"The wall clock I bought for our living room matches the decor perfectly. It is quiet, easy to read and arrived well packed. I would love to see more sizes."},
{name:"Bilal Ahmed",title:"Smooth shopping experience",rating:5,date:"2026-09-17",text:"The website is fast and simple to use. The filters helped me find a watch within my budget in minutes, and the discount was applied automatically at checkout."},
{name:"Fatima Zahra",title:"Perfect gift choice",rating:5,date:"2026-10-02",text:"I chose a women's watch for my sister and she loved it. The product photos matched what I received, and the support team replied quickly on WhatsApp."},
{name:"Usman Raza",title:"Stylish and reliable",rating:4,date:"2026-10-19",text:"Good looking automatic watch with a sturdy build. The price list page made it easy to compare models. A little more detail on warranty would be helpful."}
];
const REVIEWS_KEY="albertoCustomerReviews";
function readReviews(){let raw=null;try{raw=localStorage.getItem(REVIEWS_KEY);if(!raw)return[];const arr=JSON.parse(raw);if(!Array.isArray(arr))throw new Error("Stored reviews are not a list");return arr.filter(r=>r&&typeof r==="object")}catch(e){console.error("Could not read saved reviews",e);try{if(raw)localStorage.setItem(REVIEWS_KEY+"_corrupt_"+Date.now(),raw)}catch(e2){}return[]}}
function saveReviews(list){try{const json=JSON.stringify(list);localStorage.setItem(REVIEWS_KEY,json);return localStorage.getItem(REVIEWS_KEY)===json}catch(e){console.error("Could not save reviews",e);return false}}
function reviewStars(r){const n=Math.min(5,Math.max(1,Math.round(Number(r.rating))||5));return n}
try{if(navigator.storage&&navigator.storage.persist)navigator.storage.persist()}catch(e){}
window.addEventListener("storage",e=>{if(e.key===REVIEWS_KEY)renderCustomerReviews()});
window.addEventListener("pageshow",e=>{if(e.persisted)renderCustomerReviews()});
function renderCustomerReviews(){const box=$("#customer-reviews");if(!box.length)return;const reviews=readReviews().concat(FEATURED_REVIEWS);if(!reviews.length){box.html('<div class="col-12"><div class="empty-state"><h3>No reviews yet</h3><p class="text-secondary mb-0">Be the first to share your experience using the form below.</p></div></div>');return}box.html(`<div class="col-12"><div class="reviews-slider" id="reviews-slider"><div class="rs-track" tabindex="0" aria-label="Customer reviews">${reviews.map(r=>`<div class="rs-slide"><div class="review-card review-card-pro h-100"><span class="rv-quote" aria-hidden="true">&ldquo;</span><div class="rv-rating"><div class="stars rv-stars" role="img" aria-label="${reviewStars(r)} out of 5 stars">${Array.from({length:5},(_,i)=>`<span class="rv-star${i<reviewStars(r)?" on":""}" aria-hidden="true">★</span>`).join("")}</div><span class="rv-score" aria-hidden="true">${reviewStars(r)}.0</span></div><h3 class="rv-title">${escapeHtml(r.title||"Customer review")}</h3><p class="review-text">${escapeHtml(r.text)}</p><div class="rv-author"><span class="rv-avatar" aria-hidden="true">${escapeHtml((Array.from(String(r.name||"").trim())[0]||"•").toUpperCase())}</span><div class="rv-meta"><span class="rv-name">${escapeHtml(r.name)}</span>${r.date&&!isNaN(new Date(r.date))?`<span class="rv-date">${new Date(r.date).toLocaleDateString()}</span>`:""}</div></div></div></div>`).join("")}</div><div class="rs-controls"><button type="button" class="rs-btn rs-prev" aria-label="Previous reviews">&#8249;</button><div class="rs-dots"></div><button type="button" class="rs-btn rs-next" aria-label="Next reviews">&#8250;</button></div></div></div>`);initReviewSlider()}
/* Customer reviews slider (scroll-snap + arrows + dots + autoplay) */
let reviewTimer=null,reviewPaused=false,reviewResizeBound=false;
function reviewMetrics(t){const s=t.querySelector(".rs-slide");if(!s)return{step:0,per:1};const gap=parseFloat(getComputedStyle(t).columnGap)||24,step=s.offsetWidth+gap;return{step,per:Math.max(1,Math.round((t.clientWidth+gap)/step))}}
function updateReviewSlider(){const sl=document.getElementById("reviews-slider");if(!sl)return;const t=sl.querySelector(".rs-track"),m=reviewMetrics(t),pages=Math.max(1,Math.ceil(t.children.length/m.per)),dots=sl.querySelector(".rs-dots");sl.querySelector(".rs-controls").style.display=t.scrollWidth>t.clientWidth+4?"":"none";if(dots.children.length!==pages)dots.innerHTML=Array.from({length:pages},(_,i)=>`<button type="button" class="rs-dot" data-page="${i}" aria-label="Reviews page ${i+1}"></button>`).join("");const atEnd=t.scrollLeft+t.clientWidth>=t.scrollWidth-4,cur=atEnd?pages-1:Math.min(pages-1,Math.round(t.scrollLeft/(m.step*m.per)||0));[...dots.children].forEach((d,i)=>d.classList.toggle("active",i===cur))}
function reviewMove(dir){const sl=document.getElementById("reviews-slider");if(!sl)return;const t=sl.querySelector(".rs-track"),m=reviewMetrics(t),amt=m.step*m.per,max=t.scrollWidth-t.clientWidth;if(max<=4)return;if(dir>0)t.scrollTo({left:t.scrollLeft>=max-4?0:Math.min(max,t.scrollLeft+amt),behavior:"smooth"});else t.scrollTo({left:t.scrollLeft<=4?max:Math.max(0,t.scrollLeft-amt),behavior:"smooth"})}
function initReviewSlider(){const sl=document.getElementById("reviews-slider");if(!sl)return;const t=sl.querySelector(".rs-track");t.addEventListener("scroll",updateReviewSlider,{passive:true});if(!reviewResizeBound){window.addEventListener("resize",updateReviewSlider);reviewResizeBound=true}updateReviewSlider();clearInterval(reviewTimer);if(window.matchMedia&&matchMedia("(prefers-reduced-motion: reduce)").matches)return;reviewTimer=setInterval(()=>{if(!document.getElementById("reviews-slider")){clearInterval(reviewTimer);return}if(!reviewPaused&&!document.hidden)reviewMove(1)},5000)}
