function applyFilters(){let term=($("#product-search").val()||"").toLowerCase(),cat=$("#category-filter").val(),max=Number($("#max-price").val()||1e9),sort=$("#sort-filter").val();let a=PRODUCTS.filter(p=>(!term||(p.name+" "+p.category+" "+p.description).toLowerCase().includes(term))&&(!cat||p.category===cat)&&p.price<=max);if(sort==="price-asc")a.sort((x,y)=>x.price-y.price);if(sort==="price-desc")a.sort((x,y)=>y.price-x.price);if(sort==="name-asc")a.sort((x,y)=>x.name.localeCompare(y.name));if(sort==="name-desc")a.sort((x,y)=>y.name.localeCompare(x.name));if(sort==="rating-desc")a.sort((x,y)=>y.rating-x.rating);$("#product-grid").html(a.map(productCard).join(""));$("#result-count").text(`${a.length} of ${PRODUCTS.length} products`);$("#no-results").toggleClass("d-none",a.length!==0)}
