 /* ===== Hero video carousel: play one video fully, then slide to the next automatically ===== */
 const HERO_ID="watchVideoCarousel";
 const heroEl=()=>document.getElementById(HERO_ID);
 const heroFailed=new Set();
 function heroSafePlay(v){if(!v)return;v.muted=true;const pr=v.play();if(pr&&typeof pr.catch==="function")pr.catch(()=>{});}
 function heroGoNext(){const el=heroEl();if(!el||!window.bootstrap)return;bootstrap.Carousel.getOrCreateInstance(el,{interval:false,ride:false,pause:false,wrap:true}).next();}
 function syncHeroVideos(){
   const el=heroEl();if(!el)return;
   el.querySelectorAll(".carousel-item").forEach(item=>{
     const v=item.querySelector("video");if(!v)return;
     if(item.classList.contains("active")){if(!document.hidden)heroSafePlay(v);}
     else{v.pause();try{v.currentTime=0}catch(e){}}
   });
 }
 /* Video finished -> next slide (listeners are on document so they survive page re-renders) */
 document.addEventListener("ended",function(e){
   const v=e.target;if(!(v instanceof HTMLVideoElement))return;
   const item=v.closest("#"+HERO_ID+" .carousel-item");
   if(item&&item.classList.contains("active"))heroGoNext();
 },true);
 /* A video that fails to load must not freeze the carousel */
 document.addEventListener("error",function(e){
   const t=e.target;if(!t||!t.closest)return;
   const item=t.closest("#"+HERO_ID+" .carousel-item");
   if(!item||!item.classList.contains("active"))return;
   heroFailed.add(item);
   if(heroFailed.size<heroEl().querySelectorAll(".carousel-item").length)setTimeout(heroGoNext,800);
 },true);
 /* A video that stalls for too long is skipped */
 document.addEventListener("stalled",function(e){
   const v=e.target;if(!(v instanceof HTMLVideoElement))return;
   const item=v.closest("#"+HERO_ID+" .carousel-item");if(!item||!item.classList.contains("active"))return;
   clearTimeout(v._stallT);v._stallT=setTimeout(()=>{if(v.readyState<3&&item.classList.contains("active"))heroGoNext();},12000);
 },true);
 document.addEventListener("playing",function(e){if(e.target&&e.target._stallT)clearTimeout(e.target._stallT);},true);
 /* Slide starts: start the incoming video from 0 so it is already playing during the fade */
 document.addEventListener("slide.bs.carousel",function(e){
   if(!e.target||e.target.id!==HERO_ID)return;
   const next=e.relatedTarget&&e.relatedTarget.querySelector("video");
   if(next){try{next.currentTime=0}catch(err){}heroSafePlay(next);}
 });
 /* Slide finished: pause/reset the outgoing videos, make sure the active one is playing */
 document.addEventListener("slid.bs.carousel",function(e){
   if(!e.target||e.target.id!==HERO_ID)return;
   syncHeroVideos();
 });
 /* Pause when the tab is hidden, resume when visible */
 document.addEventListener("visibilitychange",()=>{
   const el=heroEl();if(!el)return;
   const v=el.querySelector(".carousel-item.active video");if(!v)return;
   if(document.hidden)v.pause();else heroSafePlay(v);
 });
 syncHeroVideos();

