/* Menu fade in / fade out: dropdown (Explore) and the mobile menu */
(function(){
 const FADE_OUT_MS=220,COLLAPSE_MS=350;
 // Dropdown: fade-in is done in CSS; for fade-out we let the menu fade first and only then let Bootstrap hide it
 document.addEventListener("hide.bs.dropdown",function(e){
  const toggle=e.target,wrap=toggle&&toggle.closest?toggle.closest(".site-nav .dropdown"):null,menu=wrap?wrap.querySelector(".dropdown-menu"):null;
  if(!menu)return;
  if(menu.dataset.fadeDone==="1"){delete menu.dataset.fadeDone;return}
  e.preventDefault();
  if(menu.classList.contains("menu-fade-out"))return;
  menu.classList.add("menu-fade-out");
  setTimeout(function(){menu.dataset.fadeDone="1";bootstrap.Dropdown.getOrCreateInstance(toggle).hide();menu.classList.remove("menu-fade-out");delete menu.dataset.fadeDone},FADE_OUT_MS);
 });
 // Mobile menu (hamburger): fade together with the height slide
 const isNav=e=>e.target&&e.target.id==="mainNav";
 const clearFade=el=>el.getAnimations().forEach(a=>a.cancel());
 document.addEventListener("show.bs.collapse",function(e){if(!isNav(e))return;clearFade(e.target);e.target.animate([{opacity:0},{opacity:1}],{duration:COLLAPSE_MS,easing:"ease"})});
 document.addEventListener("hide.bs.collapse",function(e){if(!isNav(e))return;clearFade(e.target);e.target.animate([{opacity:1},{opacity:0}],{duration:COLLAPSE_MS,easing:"ease",fill:"forwards"})});
 document.addEventListener("hidden.bs.collapse",function(e){if(isNav(e))clearFade(e.target)});
})();
